import * as peg from '../../cql/parser.min.js'
import { Query } from '../query.js'

export class QueryCache extends Map {

  cached (strings, ...args) {
    if (!strings?.raw) return this.parse (strings, ...args)
    const cached = this.get (strings)
    if (cached) {
      const q = new Query.for[cached.kind]
      q[q.kind] = cached[cached.kind]
      q.params = cached.params
      if (args?.length) q.args = args
      return q
    } else {
      const q = this.parse (strings, ...args)
      this.set (strings, q)
      return q
    }
  }

  parse (strings, ...args) {
    const src = String.raw (strings, ...'?'.repeat(args.length))
    return peg.parse (src, {args})
  }

  get enabled () { return peg.parse.late_binding }
  set enabled (v) {
    this.query4 = v ? this.cached : this.parse
    peg.parse.late_binding = v
  }

  query4 = this.parse
}
